<script setup lang="ts">
import { ref,computed } from 'vue'
import { useRoute } from 'vue-router'
import { useContinuity } from '../stores/continuity'
import { usePlatform } from '../stores/platform'
import { csv,download } from '../utils/files'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const c=useContinuity(),s=usePlatform(),route=useRoute(),analytics=computed(()=>route.params.page==='analytics');const search=ref(''),status=ref('全部'),archive=ref<any>(null)
const records=computed(()=>[...s.data.attempts.filter(a=>a.status!=='在考').map(a=>({id:a.id,name:a.candidate,anonymous:a.anonymous,title:s.data.sessions.find(e=>e.id===a.sessionId)?.name||'',objective:a.objective,subjective:a.subjective,total:a.subjective===null?null:a.objective+a.subjective,status:a.status,source:'现场演示答卷',version:a.version})),...s.data.marks.filter(m=>m.attemptId.startsWith('HIST')).map(m=>({id:m.id,name:m.anonymous,anonymous:m.anonymous,title:m.title,objective:m.objective,subjective:m.final,total:m.final===null?null:m.objective+m.final,status:m.status,source:'预置合成历史',version:1}))])
const shown=computed(()=>records.value.filter(r=>(!search.value||r.name.includes(search.value)||r.title.includes(search.value))&&(status.value==='全部'||r.status===status.value)))
const final=computed(()=>records.value.filter(r=>r.total!==null));const avg=computed(()=>final.value.length?final.value.reduce((a,r)=>a+r.total!,0)/final.value.length:0)
const distribution=computed(()=>[{label:'90—100',min:90,max:101},{label:'80—89',min:80,max:90},{label:'70—79',min:70,max:80},{label:'60—69',min:60,max:70},{label:'60分以下',min:0,max:60}].map(b=>({...b,count:final.value.filter(r=>r.total!>=b.min&&r.total!<b.max).length})))
function exportResults(){csv('成绩汇总.csv',[['记录ID','考生/匿名号','客观分','主观分','总分','状态','来源'],...shown.value.map(r=>[r.id,r.name,r.objective,r.subjective??'待评',r.total??'待核定',r.status,r.source])]);s.audit('成绩管理','导出成绩',`${shown.value.length}条`)}
function archiveData(row:any){const a=s.data.attempts.find(a=>a.id===row.id),m=s.data.marks.find(m=>m.id===row.id||m.attemptId===row.id),bundle=a?.personId?c.archive(a.sessionId,a.personId):null;return{...row,attempt:a||null,mark:m||null,bundle,logs:s.data.logs.filter(l=>l.object===row.id||l.object===row.anonymous),attachments:[{name:'考生答卷记录',status:a?'已关联':'预置历史示例'},{name:'评分与仲裁记录',status:m?'已关联':'纯客观卷无需人工评分'},...(bundle?.attachments.map(f=>({name:f.name,status:'已归档 · '+f.time}))||[])]}}
function exportArchive(){download(`演示档案-${archive.value.id}.json`,JSON.stringify(archive.value,null,2),'application/json');s.audit('考试档案','导出合成档案',archive.value.id)}
</script>
<template><PageHead :title="analytics?'统计分析':'成绩与档案'" :subtitle="analytics?'从业务明细生成统计结果，掌握资源建设与考试评价情况。':'成绩核定、发布、回传与归档，让结果可查、过程可溯。'" eyebrow="考试与评价 / 结果管理"><RouterLink v-if="s.can('reviewAdmin')" class="button" to="/protocol/marking">阅卷任务分配</RouterLink><RouterLink v-if="s.can('affairs')" class="button" to="/protocol/skills">技能考核任务</RouterLink><button class="button" @click="exportResults"><Icon name="Download" :size="16"/>导出成绩 CSV</button><RouterLink v-if="s.can('affairs')" class="button" to="/archives">考生综合档案</RouterLink></PageHead>
<div class="mini-metrics"><div><span>答卷记录</span><strong>{{records.length}} <small>份</small></strong></div><div><span>已核定成绩</span><strong>{{final.length}} <small>份</small></strong></div><div><span>核定成绩均分</span><strong>{{avg.toFixed(1)}} <small>分</small></strong></div><div><span>已发布</span><strong>{{records.filter(r=>r.status==='已发布').length}} <small>份</small></strong></div></div>
<template v-if="analytics"><div class="analytics-grid"><section class="panel"><div class="panel-head"><h3>核定成绩分布</h3><span class="subtle-label">{{final.length}}个样本</span></div><div class="bar-chart"><div v-for="b in distribution"><div class="bar-column"><span>{{b.count}}</span><i :style="{height:Math.max(3,b.count/Math.max(1,...distribution.map(x=>x.count))*155)+'px'}"></i></div><label>{{b.label}}</label></div></div></section><section class="panel"><div class="panel-head"><h3>题库资源分布</h3><span class="subtle-label">已入库题目</span></div><div class="resource-bars"><div v-for="bank in ['母题库','子题库','通用题库']"><label>{{bank}}<strong>{{s.data.questions.filter(q=>q.status==='已入库'&&q.bank===bank).length}} 道</strong></label><div class="progress-track"><i :style="{width:s.data.questions.filter(q=>q.status==='已入库'&&q.bank===bank).length/s.stats.bank*100+'%'}"></i></div></div></div></section></div><section class="panel spaced"><div class="panel-head"><h3>题型建设情况</h3></div><table><thead><tr><th>题型</th><th>在库数量</th><th>待审核</th><th>草稿 / 退回</th><th>业务范围</th></tr></thead><tbody><tr v-for="t in ['单选题','多选题','判断题','简答题','实操步骤题','评分表题']"><td>{{t}}</td><td>{{s.data.questions.filter(q=>q.type===t&&q.status==='已入库').length}}</td><td>{{s.data.questions.filter(q=>q.type===t&&q.status.startsWith('待')).length}}</td><td>{{s.data.questions.filter(q=>q.type===t&&['草稿','已退回'].includes(q.status)).length}}</td><td>{{['实操步骤题','评分表题'].includes(t)?'技能考核':'理论考试'}}</td></tr></tbody></table></section><div class="notice spaced">样本仅为合成演示数据，不用于推断真实认定通过率或试卷信效度。经典测量学质量指标需在正式规则与充分样本下验证。</div></template>
<section v-else class="panel"><div class="tabs"><button v-for="t in ['全部','待阅卷','待仲裁','已核定','已发布']" :class="{active:status===t}" @click="status=t">{{t}}</button></div><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="16"/><input v-model="search" placeholder="搜索考生、匿名号或考试名称…"/></div><span class="filter-meta">理论与技能成绩分列，不擅自合成认定总分</span></div><div class="table-scroll"><table><thead><tr><th>考生 / 匿名号</th><th>考试 / 评阅内容</th><th>客观分</th><th>主观分</th><th>总分</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in shown"><td><strong>{{r.name}}</strong><small>{{r.source}}</small></td><td><span class="cell-title">{{r.title}}</span><small>成绩版本 V{{r.version}}</small></td><td>{{r.objective}}</td><td>{{r.subjective??'待评'}}</td><td><strong :class="r.total!==null?'text-blue':'muted'">{{r.total??'待核定'}}</strong></td><td><Badge :text="r.status"/></td><td><div class="action-group"><button class="text-button" @click="archive=archiveData(r)">档案</button><button v-if="r.status==='已核定'" class="text-button" @click="s.run(()=>s.publishResult(r.id))">发布</button><button v-if="r.status==='已发布'" class="text-button" @click="s.run(()=>s.syncResult(r.id))">回传</button></div></td></tr></tbody></table></div><Empty v-if="!shown.length"/></section>
<section v-if="!analytics" class="panel spaced"><div class="panel-head"><h3>技能考评成绩</h3><span class="subtle-label">按评分项目实际汇总</span></div><table><thead><tr><th>考生</th><th>考核内容</th><th>技能总分</th><th>状态</th><th>考评人员</th></tr></thead><tbody><tr v-for="k in s.data.skills"><td>{{k.candidate}}</td><td>{{k.questionSnapshot?.title||s.data.questions.find(q=>q.id===k.questionId)?.title}}</td><td>{{k.status==='已提交'?k.scores.reduce((a,b)=>a+b,0):'待提交'}}</td><td><Badge :text="k.status"/></td><td>{{s.people.find(p=>p.id===k.assessorId)?.name||k.assessor||'—'}}</td></tr></tbody></table></section>
<Modal v-if="archive" :title="'考试档案 · '+archive.name" wide @close="archive=null"><div class="detail-grid"><div><span>记录编号</span><strong>{{archive.id}}</strong></div><div><span>来源</span><strong>{{archive.source}}</strong></div><div><span>成绩版本</span><strong>V{{archive.version}}</strong></div><div><span>成绩状态</span><Badge :text="archive.status"/></div></div><div class="archive-files"><div v-for="f in archive.attachments"><Icon name="FileCheck2" :size="23"/><div><strong>{{f.name}}</strong><p>{{f.status}}</p></div></div></div><h4>评分记录</h4><p v-if="archive.mark">{{Object.entries(archive.mark.scores).map(([k,v])=>k+'：'+v+'分').join(' / ')}}<br/>{{archive.mark.note}}<br/>最终主观分：{{archive.mark.final??'待核定'}}</p><p v-else>本卷客观题自动判分，共{{archive.attempt?.questions.length||0}}道。</p><h4>操作追溯</h4><div class="timeline compact"><div v-for="l in archive.logs"><i></i><strong>{{l.action}}</strong><p>{{l.actor}} · {{l.time}}</p></div><p v-if="!archive.logs.length" class="muted">预置合成历史，暂无本次会话操作。</p></div><template #footer><button class="button primary" @click="exportArchive"><Icon name="Download" :size="16"/>导出合成档案 JSON</button></template></Modal>
</template>
